content.text:
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit — `collisionNormal` answers that, and frame() uses both
// to make the ball bounce off bricks instead of plowing through (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Which face of `brick` the ball (approximated by its box) hit, inferred from
// the smallest penetration depth. Returns a unit normal the ball should bounce
// off: { x, y } pointing away from the face.
export function collisionNormal(ball, brick) {
  // Distance the ball's projected left/right/top/bottom edge has gone past
  // the brick's corresponding face (positive = overlapping on that side).
  const fromLeft = Math.abs(ball.x + ball.r - brick.x);
  const fromRight = Math.abs(ball.x - ball.r - (brick.x + brick.w));
  const fromTop = Math.abs(ball.y + ball.r - brick.y);
  const fromBottom = Math.abs(ball.y - ball.r - (brick.y + brick.h));

  const min = Math.min(fromLeft, fromRight, fromTop, fromBottom);
  if (min === fromTop) return { x: 0, y: UP };
  if (min === fromBottom) return { x: 0, y: DOWN };
  if (min === fromLeft) return { x: LEFT, y: 0 };
